SOURCES = {'TEAM_NORM': {'source': 'def _norm(value: Any) -> str:\n    text = str(value or "").strip().lower()\n    text = unicodedata.normalize("NFKD", text)\n    text = "".join(ch for ch in text if not unicodedata.combining(ch))\n    text = re.sub(r"[^a-z0-9]+", " ", text)\n    return re.sub(r"\\s+", " ", text).strip()', 'sha256': '7c531604a143eb0a7f7b74dae3f787df0da819e10b490a837a707e3d9b86abf5'}, 'SPANISH_NORM': {'source': 'def _norm(value: object) -> str:\n    text = str(value or "").strip().lower()\n    text = unicodedata.normalize("NFKD", text)\n    text = "".join(ch for ch in text if not unicodedata.combining(ch))\n    text = re.sub(r"[^a-z0-9]+", " ", text)\n    return re.sub(r"\\s+", " ", text).strip()', 'sha256': '5380714c1f096ad74083ec3d1e37151027daa2c1e347f3de727bd74e34367920'}, 'TITLE': {'source': 'def _title_preserving_acronyms(text: str) -> str:\n    replacements = {\n        "Atletico": "Atlético",\n        "Mexico": "México",\n        "Copa America": "Copa América",\n        "Division": "División",\n        "Brasileirao": "Brasileirão",\n    }\n    out = str(text or "").strip()\n    for src, dst in replacements.items():\n        out = re.sub(rf"\\b{re.escape(src)}\\b", dst, out, flags=re.I)\n    return out', 'sha256': '4ebd565a0dad0966a1b7a24fe4a606305efcabef2f7e6707aaf89b3c283a4191'}}
